#' Waffle Charts (Core, Python)
#'
#' 
#' @param data .
#' @param groups .
#' @param counts .
#' @param facet .
#' @param subject .
#' @param rows .
#' @param flip .
#' @param showPlot .
#' @param show_legend .
#' @param showCases .
#' @param showExplanations .
#' @param mytitle .
#' @param legendtitle .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$missing} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$panels} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$allocation} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$wafflePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyjwaffle <- function(
    data,
    groups = NULL,
    counts = NULL,
    facet = NULL,
    subject = NULL,
    rows = 5,
    flip = FALSE,
    showPlot = TRUE,
    show_legend = FALSE,
    showCases = FALSE,
    showExplanations = FALSE,
    mytitle = "",
    legendtitle = "",
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyjwaffle requires jmvcore to be installed (restart may be required)")

    if ( ! missing(groups)) groups <- jmvcore::resolveQuo(jmvcore::enquo(groups))
    if ( ! missing(counts)) counts <- jmvcore::resolveQuo(jmvcore::enquo(counts))
    if ( ! missing(facet)) facet <- jmvcore::resolveQuo(jmvcore::enquo(facet))
    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(groups), groups, NULL),
            `if`( ! missing(counts), counts, NULL),
            `if`( ! missing(facet), facet, NULL),
            `if`( ! missing(subject), subject, NULL))

    for (v in groups) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in facet) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyjwaffleOptions$new(
        groups = groups,
        counts = counts,
        facet = facet,
        subject = subject,
        rows = rows,
        flip = flip,
        showPlot = showPlot,
        show_legend = show_legend,
        showCases = showCases,
        showExplanations = showExplanations,
        mytitle = mytitle,
        legendtitle = legendtitle,
        showConsole = showConsole)

    analysis <- pyjwaffleClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

